WITH recent_departments AS (SELECT * FROM departments WHERE budget BETWEEN 1340000 AND 1492000), departments_stats AS (SELECT CASE WHEN budget >= 3519000 THEN 'high' WHEN budget >= 1045000 THEN 'mid' ELSE 'low' END AS budget_bucket, CASE WHEN location IN ('London', 'New York') THEN 'priority' ELSE 'other' END AS location_group, MIN(budget) AS min_budget FROM recent_departments GROUP BY CASE WHEN budget >= 3519000 THEN 'high' WHEN budget >= 1045000 THEN 'mid' ELSE 'low' END, CASE WHEN location IN ('London', 'New York') THEN 'priority' ELSE 'other' END) SELECT budget_bucket, location_group, min_budget FROM departments_stats ORDER BY min_budget, budget_bucket, location_group LIMIT 20
